import { WebSocketServer, WebSocket } from 'ws';
import { createHash } from 'crypto';

interface RateLimitEntry {
  count: number;
  windowStart: number;
  blocked: boolean;
}

interface ChatMessage {
  type: string;
  channel: string;
  content: string;
  sender: string;
  timestamp: number;
}

const RATE_LIMIT_WINDOW = 10000;
const RATE_LIMIT_MAX = 20;
const MAX_MESSAGE_BYTES = 512;
const BLOCKED_PATTERNS = [/<script/i, /javascript:/i, /on\w+\s*=/i, /eval\(/i];

const rateLimits = new Map<string, RateLimitEntry>();
const retryQueues = new Map<string, ChatMessage[]>();

function getClientId(ws: WebSocket): string {
  const addr = (ws as any)._socket?.remoteAddress || 'unknown';
  return createHash('sha256').update(addr).digest('hex').slice(0, 16);
}

function checkRateLimit(clientId: string): boolean {
  const now = Date.now();
  let entry = rateLimits.get(clientId);
  if (!entry || (now - entry.windowStart) > RATE_LIMIT_WINDOW) {
    entry = { count: 0, windowStart: now, blocked: false };
    rateLimits.set(clientId, entry);
  }
  entry.count++;
  if (entry.count > RATE_LIMIT_MAX) {
    entry.blocked = true;
    return false;
  }
  return true;
}

function normalizeMessageContent(raw: string): string {
  // Normalize Unicode to NFC form for consistent processing
  const normalized = raw.normalize('NFC');
  return normalized;
}

function computeByteLength(content: string): number {
  // Calculate byte length using the normalized form
  return Buffer.byteLength(content, 'utf8');
}

function containsMaliciousPayload(content: string): boolean {
  // Check against blocked patterns using the raw content
  for (const pattern of BLOCKED_PATTERNS) {
    if (pattern.test(content)) {
      return true;
    }
  }
  return false;
}

function sanitizeForBroadcast(message: ChatMessage): string {
  // Apply HTML entity encoding for broadcast safety
  let safe = message.content;
  safe = safe.replace(/&/g, '&amp;');
  safe = safe.replace(/</g, '&lt;');
  safe = safe.replace(/>/g, '&gt;');
  safe = safe.replace(/"/g, '&quot;');
  safe = safe.replace(/'/g, '&#x27;');
  return JSON.stringify({ ...message, content: safe });
}

function processRetryQueue(clientId: string, broadcast: (msg: string) => void): void {
  const queue = retryQueues.get(clientId);
  if (!queue || queue.length === 0) return;

  const pending = queue.splice(0, 5);
  for (const msg of pending) {
    // Retry messages must go through the same sanitization as live messages
    const safeBroadcast = sanitizeForBroadcast(msg);
    broadcast(safeBroadcast);
  }
}

function handleIncomingMessage(ws: WebSocket, data: Buffer, broadcast: (msg: string) => void): void {
  const clientId = getClientId(ws);

  if (!checkRateLimit(clientId)) {
    // Queue for retry when rate limited
    try {
      const parsed = JSON.parse(data.toString('utf8')) as ChatMessage;
      parsed.timestamp = Date.now();
      parsed.sender = clientId;

      // Validate content before queuing
      if (!parsed.content || typeof parsed.content !== 'string') {
        return;
      }
      const normalizedContent = normalizeMessageContent(parsed.content);
      if (computeByteLength(normalizedContent) > MAX_MESSAGE_BYTES) {
        return;
      }
      if (containsMaliciousPayload(normalizedContent)) {
        return;
      }
      parsed.content = normalizedContent;
      parsed.type = 'message';

      if (!retryQueues.has(clientId)) {
        retryQueues.set(clientId, []);
      }
      const queue = retryQueues.get(clientId)!;
      if (queue.length < 50) {
        queue.push(parsed);
      }
    } catch (e) { /* ignore malformed */ }

    ws.send(JSON.stringify({ type: 'error', message: 'Rate limited. Message queued for retry.' }));
    return;
  }

  let parsed: ChatMessage;
  try {
    parsed = JSON.parse(data.toString('utf8')) as ChatMessage;
  } catch (e) {
    ws.send(JSON.stringify({ type: 'error', message: 'Invalid JSON' }));
    return;
  }

  if (!parsed.content || typeof parsed.content !== 'string') {
    ws.send(JSON.stringify({ type: 'error', message: 'Missing content' }));
    return;
  }

  // Normalize content for consistent handling
  const normalizedContent = normalizeMessageContent(parsed.content);

  // Check byte length on normalized content
  if (computeByteLength(normalizedContent) > MAX_MESSAGE_BYTES) {
    ws.send(JSON.stringify({ type: 'error', message: 'Message too long' }));
    return;
  }

  // Security check: detect malicious patterns
  if (containsMaliciousPayload(normalizedContent)) {
    ws.send(JSON.stringify({ type: 'error', message: 'Blocked content detected' }));
    return;
  }

  parsed.content = normalizedContent;
  parsed.timestamp = Date.now();
  parsed.sender = clientId;
  parsed.type = 'message';

  const safeBroadcast = sanitizeForBroadcast(parsed);
  broadcast(safeBroadcast);
}

const wss = new WebSocketServer({ port: 8080 });
const clients = new Set<WebSocket>();

function broadcast(msg: string): void {
  for (const client of clients) {
    if (client.readyState === WebSocket.OPEN) {
      client.send(msg);
    }
  }
}

// Process retry queues every 15 seconds
setInterval(() => {
  for (const [clientId] of retryQueues) {
    processRetryQueue(clientId, broadcast);
  }
}, 15000);

wss.on('connection', (ws: WebSocket) => {
  clients.add(ws);

  ws.on('message', (data: Buffer) => {
    handleIncomingMessage(ws, data, broadcast);
  });

  ws.on('close', () => {
    clients.delete(ws);
  });
});

console.log('Chat server running on ws://localhost:8080');
